/// <summary>
/// COC for table AgreementLine
/// Added for CB202 Sales quota by Akshay
/// </summary>
[ExtensionOf(tableStr(AgreementLine))]
final class METAgreementLineTbl_Extension
{
}

Method.Source:
/// <summary>
/// Gets the remaining qty/amount to be fulfilled by sales order line for given agreement line
/// </summary>
/// <returns>Remaining qty/amount to be fulfilled</returns>
public real metGetAgreementLineRemaining()
{
    #AgreementsRemains
    container fulfillmentValues = AgreementLine::calculateFulfillmentForLine(this);

    return conPeek(fulfillmentValues, #RemainingIndex);
}

/// <summary>
/// CB202_SalesQuotaMinMax
/// </summary>
/// <returns>True if category can be edited; otherwise, false.</returns>
public boolean canEditCategory()
{
    return next canEditCategory() || (!this.RecId && this.AgreementLineType == CommitmentType::METVendorCategoryProductVolume);
}

/// <summary>
/// Method to return the category hierarchy role from the category field lookup
/// </summary>
/// <returns><c>EcoResCategoryNamedHierarchyRole</c></returns>
EcoResCategoryNamedHierarchyRole METNamedCategoryHierarchyRole()
{
    EcoResCategoryNamedHierarchyRole ret = this.agreementHeader().METIsVendorCategoryProductVolume() ?
        EcoResCategoryNamedHierarchyRole::RetailSpecialGroup :
        EcoResCategoryNamedHierarchyRole::Sales;

    return ret;
}
